}
class Donation extends Payment {
  - earmarkedFor: Campaign
}
class Member {
  - status: String
  - uniformNotificationContract: String
}
class MembershipApplication {
  - applicationStatus: String
  - receivedFrom: Member
}
class DistrictChapter {
  - members: * Member
  - membershipApplications: * MembershipApplication
  - campaigns: * Campaign
}
class StateChapter {
  - districtChapters: * DistrictChapter
}
class Committee {
  - mandates: * Mandate
}
class Mandate {
  - termOfOffice: String
  - awardedTo: Member
}
class Campaign {
  - deployments: * Deployment
  - donations: * Donation
}
class Deployment {
  - hours: int
  - member: Member
  - campaign: Campaign
}

