Deployment "1" *-- "1" Campaign : campaign
Payment "1" *-- "1" Member : originatesFrom
MembershipFeePayment <|-- Payment
Donation <|-- Payment
DistrictChapter <|-- StateChapter
@enduml

sequenceDiagram(name  =  "PasswordReset")  {
    val user  = lifeline(name  =  "User")  { isActor  = true  }
    val webPortal  = lifeline(name  =  "Web Portal")
    val authService  = lifeline(name  =  "Authentication Service")
    val userDatabase  = lifeline(name  =  "User Database")
    val emailService  = lifeline(name  =  "Email Service")

    message(from  = user, to  = webPortal, label  =  "requestPasswordReset(email)")
    message(from  = webPortal, to  = authService, label  =  "requestPasswordReset(email)")
    message(from  = authService, to  = userDatabase, label  =  "findUserByEmail(email)")
    reply(from  = userDatabase, to  = authService, label  =  "userFound/ userNotFound")

    alt { 
        par("userFound") {
            message(from  = authService, to  = userDatabase, label  =  "generateResetTokenAndStore(userId)")
            reply(from  = userDatabase, to  = authService, label  =  "tokenStored")
            message(from  = authService, to  = emailService, label  =  "sendResetEmail(email, token)")
        }
        par("userNotFound") {
        }
    }

    message(from  = authService, to  = webPortal, label  =  "passwordResetRequestProcessed")
    reply(from  = webPortal, to  = user, label  =  "passwordResetRequestReceived")
}

sequenceDiagram(name = "Advanced Driver Assistance System") {
    val camera = lifeline(name = "Camera Sensor") { isActor = true }
    val radar = lifeline(name = "Radar Sensor") { isActor = true }
    val fusionUnit = lifeline(name = "Fusion Unit")
    val emergencyBrakingAssistant = lifeline(name = "Emergency Braking Assistant")
    val controlUnit = lifeline(name = "Control Unit")
    val driver = lifeline(name = "Driver") { isActor = true }

    message(from = camera, to = fusionUnit, label = "measurement data")
    message(from = radar, to = fusionUnit, label = "measurement data")

    reply(from = fusionUnit, to = camera, label = "")
    reply(from = fusionUnit, to = radar, label = "")

    message(from = fusionUnit, to = emergencyBrakingAssistant, label = "consolidated environment model and collision risk")

    alt(condition = "timeToCollision < criticalThreshold") {
        message(from = emergencyBrakingAssistant, to = driver, label = "acoustic warning")
        message(from = emergencyBrakingAssistant, to = controlUnit, label = "initiate autonomous braking")
        loop() {
            message(from = controlUnit, to = emergencyBrakingAssistant, label = "brake pressure adjustment")
            reply(from = emergencyBrakingAssistant, to = controlUnit, label = "")
        }
        message(from = emergencyBrakingAssistant, to = controlUnit, label = "end braking maneuver")
        message(from = emergencyBrakingAssistant, to = controlUnit, label = "record event in diagnostic log")
    } else {
        message(from = emergencyBrakingAssistant, to = driver, label = "distance warning")
        message(from = emergencyBrakingAssistant, to = controlUnit, label = "log observed risk")
    }
}

