import dev.kuml.sysml2.dsl.sysml2Model

sysml2Model(name  =  "ADASModel")  {
    val sensor  = partDef(name  =  "Sensor", isAbstract  = true)
    val camera  = partDef(name  =  "Camera")  {
        generalization(typeId  = sensor.id)
    }
    val radar  = partDef(name  =  "Radar")  {
        generalization(typeId  = sensor.id)
    }
    val lidar  = partDef(name  =  "Lidar")  {
        generalization(typeId  = sensor.id)
    }
    val sensorSuite  = partDef(name  =  "Sensor Suite")  {
        part(name  =  "camera", typeId  = camera.id)
        part(name  =  "radar", typeId  = radar.id)
        part(name  =  "lidar", typeId  = lidar.id)
    }
    val fusionUnit  = partDef(name  =  "Fusion and Processing Unit")
    val driverAssistanceControlUnit  = partDef(name  =  "Driver Assistance Control Unit")
    val steeringSystem  = partDef(name  =  "Steering System")
    val brakingSystem  = partDef(name  =  "Braking System")
    val adasSubsystem  = partDef(name  =  "ADAS Subsystem")  {
        part(name  =  "sensorSuite", typeId  = sensorSuite.id)
        part(name  =  "fusionUnit", typeId  = fusionUnit.id)
        part(name  =  "driverAssistanceControlUnit", typeId  = driverAssistanceControlUnit.id)
    }
    val environmentModel  = partDef(name  =  "Environment Model")
    val driverAssistanceControlUnitInternals  = partDef(name  =  "Driver Assistance Control Unit Internals")  {
        part(name  =  "environmentModel", typeId  = environmentModel.id)
    }
    bdd(name  =  "ADASModel BDD")  {
        include(adasSubsystem)
        include(sensor)
        include(camera)
        include(radar)
        include(lidar)
        include(sensorSuite)
        include(fusionUnit)
        include(driverAssistanceControlUnit)
        include(driverAssistanceControlUnitInternals)
        include(environmentModel)
        include(steeringSystem)
        include(brakingSystem)
    }
}

